  {
    "id": "fac64e16-0e7b-5ab8-85c9-fdcc63d580fd", "type": "c1_lex_comerc", "sort_order": 5,
    "title": "Activitats comercials i transaccionals", "name": "Compravenda, lloguer, banca, pagaments, factures, impostos, contractes, consum i reclamacions",
    "content": "El vocabulari formal de les transaccions: compravenda i arrendament, fiança i hipoteca, comandes, albarans, factures i rebuts, impostos (IVA, IRPF, base imposable), operacions bancàries (saldo, ingrés, transferència, domiciliació), contractes (rescindir, prorrogar) i drets del consumidor (garantia, devolució, reclamació), amb les alternatives genuïnes als castellanismes més freqüents (3.2.3).", "icon": "🛒", "color": "#FFF9C4",
    "exercises": [
      {"q": "El contracte pel qual una persona transferix la propietat d'un bé a una altra a canvi d'un preu és...", "o": ["la compravenda", "l'arrendament", "la fiança"], "e": "La compravenda (comprar + vendre). L'arrendament cedix l'ús d'un bé, no la propietat."},
      {"q": "En un contracte d'arrendament, la persona que cedix l'ús de l'immoble és...", "o": ["l'arrendador", "l'arrendatari", "el fiador"], "e": "Arrendador: qui cedix el bé. Arrendatari (o llogater): qui el rep i paga el lloguer."},
      {"q": "La persona que es compromet a pagar un deute si el deutor principal no ho fa és...", "o": ["el fiador", "el creditor", "el beneficiari"], "e": "El fiador respon del deute d'un altre. El creditor és qui ha de cobrar."},
      {"q": "Els diners que es deixen en dipòsit en llogar un pis, com a garantia, són...", "o": ["la fiança", "la hipoteca", "la quota"], "e": "La fiança es torna en acabar el contracte si no hi ha desperfectes."},
      {"q": "El préstec per a comprar un immoble, garantit amb el mateix immoble, és...", "o": ["una hipoteca", "un aval", "una fiança"], "e": "Una hipoteca (hipotecar, hipotecari). Si no es paga, el banc pot quedar-se l'immoble."},
      {"q": "Quina expressió és correcta?", "o": ["pagar a terminis", "pagar a plaços", "pagar a plassos"], "e": "Pagar a terminis (en diversos pagaments). «Plazo» es diu «termini»."},
      {"q": "Una quantitat de diners que s'avança a compte d'un pagament és...", "o": ["una bestreta", "un adelant", "un adelanto"], "e": "Una bestreta (o un avançament). «Adelanto» és castellà."},
      {"q": "Quina expressió és correcta?", "o": ["pagar per avançat", "pagar per adelantat", "pagar adelantat"], "e": "Pagar per avançat (o per endavant). «Adelantar» és un castellanisme."},
      {"q": "L'encàrrec de mercaderies que un client fa a un proveïdor és...", "o": ["una comanda", "un pedido", "un pedit"], "e": "Fer una comanda. «Pedido» és un castellanisme."},
      {"q": "L'empresa que subministra els productes a una botiga és...", "o": ["el proveïdor", "el proveedor", "el provehidor"], "e": "El proveïdor (proveir), amb dièresi en la i."},
      {"q": "El document que acompanya la mercaderia i que el client signa en rebre-la és...", "o": ["l'albarà", "l'albarán", "la nòmina"], "e": "L'albarà acredita el lliurament de la mercaderia; després es fa la factura."},
      {"q": "El document que acredita que s'ha pagat una quantitat és...", "o": ["el rebut", "el recibo", "la rebuda"], "e": "El rebut (de la llum, del lloguer...). La rebuda és l'acció de rebre."},
      {"q": "El càlcul previ del cost d'una obra o d'un servici és...", "o": ["el pressupost", "el pressupòsit", "el presupost"], "e": "El pressupost. Un pressupòsit és un supòsit previ, una altra cosa."},
      {"q": "En una factura, l'import sobre el qual s'aplica l'impost és...", "o": ["la base imposable", "el preu final", "el descompte"], "e": "La base imposable; si se li afig l'IVA, s'obté el total de la factura."},
      {"q": "Què vol dir la sigla IVA?", "o": ["impost sobre el valor afegit", "impost sobre el valor agregat", "impost sobre la venda afegida"], "e": "IVA: impost sobre el valor afegit. Grava el consum de béns i servicis."},
      {"q": "L'impost que grava els ingressos de les persones físiques és...", "o": ["l'IRPF", "l'IVA", "l'IBI"], "e": "IRPF: impost sobre la renda de les persones físiques. L'IBI grava els béns immobles."},
      {"q": "Retindre judicialment els béns d'un deutor per a cobrar un deute és...", "o": ["embargar-los", "hipotecar-los", "avalar-los"], "e": "Embargar: l'embargament. Hipotecar és posar un bé com a garantia d'un préstec."},
      {"q": "Els diners que una entitat deixa amb l'obligació de tornar-los amb interessos són...", "o": ["un préstec", "un préstamo", "un prèstam"], "e": "Un préstec (prestar). «Préstamo» és castellà."},
      {"q": "La quantitat fixa que es paga periòdicament (a un club, a una associació...) és...", "o": ["la quota", "la cuota", "la cota"], "e": "La quota. La cota és una altura o un nivell, una altra paraula."},
      {"q": "La quantitat de diners que hi ha en un compte bancari en un moment determinat és...", "o": ["el saldo", "el deute", "el rèdit"], "e": "El saldo del compte. El rèdit és el benefici que produïx un capital."},
      {"q": "Quan s'ha gastat més diners dels que hi ha en el compte, el compte està...", "o": ["en descobert", "en blanc", "al dia"], "e": "Un compte en descobert té saldo negatiu."},
      {"q": "Posar diners en el teu compte bancari és...", "o": ["ingressar-los", "reintegrar-los", "transferir-los"], "e": "Ingressar (un ingrés). Transferir és enviar-los a un altre compte."},
      {"q": "Enviar diners d'un compte a un altre és fer...", "o": ["una transferència", "un ingrés", "una domiciliació"], "e": "Una transferència (bancària)."},
      {"q": "Fer que el banc pague automàticament els rebuts de la llum des del teu compte és ___ els rebuts.", "o": ["domiciliar", "endossar", "embargar"], "e": "Domiciliar els rebuts: la domiciliació bancària."},
      {"q": "Quina és la forma correcta?", "o": ["pagar amb targeta", "pagar amb tarjeta", "pagar amb targueta"], "e": "La targeta (de crèdit, de dèbit). «Tarjeta» és castellà."},
      {"q": "Quina és la forma correcta?", "o": ["un bitllet de vint euros", "un billet de vint euros", "un billete de vint euros"], "e": "El bitllet (de banc, de tren...), amb tl."},
      {"q": "Pagar amb monedes i bitllets, sense targeta, és pagar...", "o": ["en efectiu", "a crèdit", "a terminis"], "e": "En efectiu (o en metàl·lic)."},
      {"q": "Els diners que et tornen quan pagues amb un bitllet de més valor són...", "o": ["el canvi", "el vuelto", "el suelto"], "e": "El canvi (tornar el canvi). «Vuelto» i «suelto» són castellanismes."},
      {"q": "Els diners que gasta una empresa o una família són...", "o": ["les despeses", "els gastos", "els gasts"], "e": "Les despeses (ingressos i despeses). «Gastos» és castellà."},
      {"q": "Vendre en grans quantitats, normalment a altres comerciants, és vendre...", "o": ["a l'engròs", "a la menuda", "al por major"], "e": "A l'engròs (majorista). «Al por mayor» és castellà."},
      {"q": "La persona que adquirix béns o servicis per a ús propi és...", "o": ["el consumidor", "el proveïdor", "el distribuïdor"], "e": "El consumidor. Les associacions de consumidors defenen els seus drets."},
      {"q": "El període durant el qual el venedor respon dels defectes d'un producte és...", "o": ["la garantia", "la devolució", "la fiança"], "e": "La garantia (un producte en garantia)."},
      {"q": "Quina és la forma genuïna?", "o": ["un descompte del 20 %", "un descuent del 20 %", "un descont del 20 %"], "e": "Un descompte (descomptar). Les altres formes no són correctes."},
      {"q": "Anul·lar un contracte abans que s'acabe el termini és...", "o": ["rescindir-lo", "prorrogar-lo", "subscriure'l"], "e": "Rescindir (la rescissió). Prorrogar és allargar-ne la durada; subscriure'l és signar-lo."},
      {"q": "Allargar la durada d'un contracte és...", "o": ["prorrogar-lo", "rescindir-lo", "rubricar-lo"], "e": "Prorrogar (una pròrroga)."},
      {"q": "Quina paraula NO pertany a l'àmbit bancari?", "o": ["la cartellera", "el saldo", "la transferència", "la domiciliació"], "e": "La cartellera és dels espectacles; les altres són operacions o conceptes bancaris."},
      {"q": "Escriu la paraula genuïna per a «alquiler» (pagar el ___ del pis).", "a": ["lloguer"], "e": "El lloguer."},
      {"q": "Escriu la forma genuïna de «recibo» (el ___ de la llum).", "a": ["rebut"], "e": "El rebut."},
      {"q": "Escriu la forma genuïna de «plazos» (pagar a ___).", "a": ["terminis"], "e": "Pagar a terminis."},
      {"q": "Escriu la forma genuïna de «préstamo» (demanar un ___ al banc).", "a": ["préstec"], "e": "Un préstec."},
      {"q": "Escriu la forma genuïna de «gastos» (les ___ del mes).", "a": ["despeses"], "e": "Les despeses."},
      {"q": "Escriu la forma genuïna de «renta» (la declaració de la ___).", "a": ["renda"], "e": "La declaració de la renda."},
      {"q": "Escriu l'antònim de «creditor»: qui deu diners és el ___.", "a": ["deutor"], "e": "Deutor, deutora."},
      {"q": "Escriu el nom del contracte de comprar i vendre, compost de dos verbs (c___).", "a": ["compravenda"], "e": "La compravenda, escrit junt."},
      {"q": "Escriu el nom de la quantitat avançada a compte d'un pagament (b___).", "a": ["bestreta"], "e": "Una bestreta."}
