      {"q": "El grup de professors que avalua una tesi o una oposició és...", "o": ["el tribunal", "el claustre", "el consell escolar"], "e": "El tribunal qualifica la prova."},
      {"q": "La unitat de mesura del treball acadèmic de l'estudiant en l'educació superior europea és...", "o": ["el crèdit (ECTS)", "el curs", "el trimestre"], "e": "Un grau de quatre anys sol tindre 240 crèdits ECTS."},
      {"q": "El conjunt d'assignatures i crèdits que formen una titulació és...", "o": ["el pla d'estudis", "el calendari escolar", "l'horari"], "e": "El pla d'estudis d'un grau o d'un màster."},
      {"q": "La qualificació màxima, que es concedix a resultats excepcionals, és...", "o": ["la matrícula d'honor", "el notable", "el suficient"], "e": "La matrícula d'honor (MH) s'atorga sobre un excel·lent."},
      {"q": "L'exposició del professor davant de tot el grup, amb poca participació de l'alumnat, és...", "o": ["la classe magistral", "el seminari", "la tutoria"], "e": "La classe (o lliçó) magistral. En el seminari es treballa en grup reduït."},
      {"q": "La sessió de treball en grup reduït, amb participació activa de l'alumnat, és...", "o": ["un seminari", "una classe magistral", "una conferència"], "e": "Un seminari."},
      {"q": "La comunicació que es presenta en un congrés per a debatre-la és...", "o": ["una ponència", "una tutoria", "una matrícula"], "e": "Una ponència; qui la presenta és el ponent."},
      {"q": "La ciència que estudia l'educació i els mètodes d'ensenyament és...", "o": ["la pedagogia", "la filologia", "la psicologia"], "e": "La pedagogia (pedagog, pedagògic)."},
