      {"q": "Quina parella de paraules són sinònims correctes?", "o": ["ensenyança - ensenyament", "ensenyança - enseñança", "ensenyament - ensenyatge"], "e": "Ensenyança i ensenyament són sinònims; les altres formes no existixen."},
      {"q": "Quina és la forma correcta?", "o": ["l'aprenentatge", "l'aprenentage", "l'aprenentatje"], "e": "Aprenentatge, amb -tge."},
      {"q": "La no-assistència habitual a classe sense justificació és...", "o": ["l'absentisme escolar", "l'abandonament escolar", "la repetició de curs"], "e": "Absentisme: no assistir. Abandonament: deixar els estudis abans d'acabar-los."},
      {"q": "Deixar els estudis abans d'acabar-los és...", "o": ["l'abandonament escolar", "l'absentisme escolar", "l'excedència"], "e": "L'abandonament escolar (prematur)."},
      {"q": "Quina és la forma genuïna?", "o": ["l'assetjament escolar", "l'acoso escolar", "l'acosament escolar"], "e": "L'assetjament escolar (assetjar). «Acoso» és castellà."},
      {"q": "L'alumne que torna a fer el mateix curs perquè no l'ha superat és...", "o": ["repetidor", "repetint", "repetent"], "e": "Un alumne repetidor (repetir curs)."},
      {"q": "La formació que es fa al llarg de la vida laboral per a actualitzar coneixements és la formació...", "o": ["contínua", "inicial", "obligatòria"], "e": "La formació contínua (o permanent). La inicial és la que es rep abans d'exercir."},
      {"q": "Els estudis que conduïxen a un títol oficial són l'ensenyament...", "o": ["reglat", "lliure", "informal"], "e": "L'ensenyament reglat (oficial). Un curset d'afició és ensenyament no reglat."},
      {"q": "Estudiar sense assistir a classes presencials, per mitjans telemàtics, és estudiar...", "o": ["a distància", "en règim presencial", "en règim intern"], "e": "L'ensenyament a distància és l'antònim del presencial."},
      {"q": "El professional del centre que assessora l'alumnat sobre els estudis i les eixides professionals és...", "o": ["l'orientador", "el bidell", "l'interventor"], "e": "L'orientador (o l'orientadora) escolar."},
      {"q": "Quina expressió és correcta?", "o": ["les eixides professionals", "les salides professionals", "les salidas professionals"], "e": "Eixides (o sortides) professionals. «Salida» és castellà."},
      {"q": "Les tasques que l'alumnat ha de fer a casa són...", "o": ["els deures", "els deberes", "les tareas"], "e": "Fer els deures. «Deberes» i «tareas» són castellanismes."},
      {"q": "Les notes que pren l'estudiant durant la classe són...", "o": ["els apunts", "els apuntes", "les anotes"], "e": "Prendre apunts."},
      {"q": "La llista de les obres consultades que es posa al final d'un treball és...", "o": ["la bibliografia", "l'índex", "l'annex"], "e": "La bibliografia. L'índex indica el contingut i les pàgines."},
      {"q": "Copiar l'obra d'un altre fent-la passar per pròpia és...", "o": ["plagiar", "citar", "parafrasejar"], "e": "Plagiar (un plagi). Citar és reproduir indicant-ne l'autor."},
      {"q": "Quina paraula NO pertany a l'àmbit universitari?", "o": ["l'albarà", "el deganat", "el rectorat", "el doctorat"], "e": "L'albarà és un document comercial; les altres són de la universitat."},
      {"q": "En l'expressió «personal docent i investigador», «docent» vol dir...", "o": ["que ensenya", "que estudia", "que administra"], "e": "Docent: relatiu a l'ensenyament o que ensenya (la docència)."},
