      {"q": "L'autorització que es posa en el passaport per a entrar en determinats països és...", "o": ["el visat", "el visado", "el visatge"], "e": "El visat. «Visado» és castellà."},
      {"q": "La descripció d'un recorregut amb els llocs per on es passa és...", "o": ["l'itinerari", "l'inventari", "l'horari"], "e": "L'itinerari d'un viatge o d'una ruta."},
      {"q": "Quina és la forma correcta?", "o": ["el recorregut", "el recorrit", "el recorrido"], "e": "El recorregut (recórrer)."},
      {"q": "Un recorregut per un museu o un monument acompanyat d'una persona que dona explicacions és...", "o": ["una visita guiada", "una visita lliure", "una estada"], "e": "Una visita guiada (amb guia)."},
      {"q": "La finestreta on es venen les entrades o els bitllets és...", "o": ["la taquilla", "la recepció", "la consigna"], "e": "La taquilla. La consigna és el lloc on es deixa l'equipatge en dipòsit."},
      {"q": "El lloc d'una estació on es pot deixar l'equipatge en dipòsit és...", "o": ["la consigna", "la taquilla", "l'andana"], "e": "La consigna."},
      {"q": "El conjunt de béns culturals i naturals heretats que cal conservar és...", "o": ["el patrimoni", "el paisatge", "el pressupost"], "e": "El patrimoni (cultural, natural, arquitectònic)."},
      {"q": "Un edifici religiós xicotet, normalment fora del nucli urbà, és...", "o": ["una ermita", "una catedral", "una basílica"], "e": "Una ermita (ermità, ermitana)."},
      {"q": "L'edifici on viu una comunitat de monjos és...", "o": ["un monestir", "un monasterio", "un monestiri"], "e": "Un monestir. «Monasterio» és castellà."},
      {"q": "L'oficina que facilita informació als visitants d'una població és...", "o": ["l'oficina de turisme", "la consergeria", "la consigna"], "e": "L'oficina de turisme (o d'informació turística)."},
      {"q": "El camí estret i senyalitzat per a fer excursions a peu és...", "o": ["un sender", "una autovia", "un carril"], "e": "Un sender (o una senda). D'ací, el senderisme."},
      {"q": "Instal·lar una tenda de campanya i dormir-hi a l'aire lliure és...", "o": ["acampar", "acampejar", "acampanar"], "e": "Acampar (una acampada)."},
      {"q": "Quina és la forma correcta?", "o": ["una tenda de campanya", "una tenda de campaña", "una casa de campanya"], "e": "Una tenda de campanya."},
      {"q": "Quina paraula NO pertany al transport aeri?", "o": ["la rodalia", "l'escala", "l'embarcament", "la facturació"], "e": "La rodalia s'associa als trens de proximitat."},
      {"q": "Escriu la forma genuïna de «equipaje» (l'___).", "a": ["equipatge"], "e": "L'equipatge."},
      {"q": "Escriu la forma genuïna de «andén» (l'___).", "a": ["andana"], "e": "L'andana."},
      {"q": "Escriu la forma genuïna de «crucero» (un ___ pel Mediterrani).", "a": ["creuer"], "e": "Un creuer."},
