      {"q": "Transferir un fitxer des d'internet al teu dispositiu és...", "o": ["baixar-lo (o descarregar-lo)", "penjar-lo", "compartir-lo"], "e": "Baixar o descarregar. Penjar és el procés contrari."},
      {"q": "Posar una foto o un document en una pàgina web o en una xarxa social és...", "o": ["penjar-lo", "baixar-lo", "descarregar-lo"], "e": "Penjar un fitxer a la xarxa."},
      {"q": "La persona que navega per internet és...", "o": ["un internauta", "un informàtic", "un telefonista"], "e": "Internauta."},
      {"q": "L'ordinador que emmagatzema i proporciona dades a altres ordinadors connectats en xarxa és...", "o": ["el servidor", "el navegador", "el ratolí"], "e": "El servidor. El navegador és el programa per a visitar pàgines web."},
      {"q": "Quin verb indica que escrius amb el teclat?", "o": ["teclejar", "teclar", "tecletejar"], "e": "Teclejar."},
      {"q": "Un conjunt d'instruccions ordenades per a resoldre un problema, base de qualsevol programa, és...", "o": ["un algorisme", "un logaritme", "un aforisme"], "e": "Algorisme. El logaritme és un concepte matemàtic; l'aforisme, una sentència breu."},
      {"q": "Una connexió de gran capacitat per a transmetre moltes dades a gran velocitat és de banda...", "o": ["ampla", "llarga", "gran"], "e": "Banda ampla."},
      {"q": "Una reunió a distància amb imatge i so per internet és...", "o": ["una videoconferència", "un videoclip", "una videoconsola"], "e": "Videoconferència."},
      {"q": "La figureta feta amb caràcters o dibuixada que expressa un estat d'ànim en un missatge és...", "o": ["una emoticona", "un logotip", "un rètol"], "e": "Emoticona."},
      {"q": "La zona on el telèfon mòbil rep senyal és la...", "o": ["cobertura", "coberta", "cobrança"], "e": "Cobertura (no tindre cobertura)."},
      {"q": "La xifra que s'afig davant d'un número de telèfon per a trucar a un altre país és...", "o": ["el prefix", "el sufix", "l'infix"], "e": "El prefix internacional."},
      {"q": "Una tarifa que permet un consum il·limitat per un preu fix és una tarifa...", "o": ["plana", "rasa", "oberta"], "e": "Tarifa plana."},
      {"q": "L'aparell o servici que enregistra els missatges quan no pots atendre una telefonada és...", "o": ["el contestador automàtic", "el despertador", "l'altaveu"], "e": "Contestador automàtic."},
      {"q": "Les persones que reben les publicacions d'un perfil en una xarxa social són els seus...", "o": ["seguidors", "perseguidors", "seguiments"], "e": "Seguidors (seguir un perfil)."},
      {"q": "La informació falsa difosa intencionadament com si fora una notícia és...", "o": ["una notícia falsa", "una notícia breu", "una exclusiva"], "e": "Notícia falsa. L'exclusiva és una notícia que només dona un mitjà."},
      {"q": "Quina paraula NO pertany al vocabulari de la informàtica?", "o": ["el pentagrama", "el teclat", "la carpeta", "l'escriptori"], "e": "El pentagrama és de la música; carpeta i escriptori tenen també un sentit informàtic."},
      {"q": "En la pantalla de l'ordinador, l'espai inicial amb les icones dels programes i les carpetes és...", "o": ["l'escriptori", "el tauler", "el calaix"], "e": "L'escriptori (sentit figurat de la taula de treball)."},
      {"q": "Quina parella anglicisme – forma genuïna és correcta?", "o": ["link – enllaç", "hardware – programari", "spam – correu fem"], "e": "Link: enllaç. Hardware és el maquinari; spam, el correu brossa."},
      {"q": "I ara, quina d'estes parelles anglicisme – forma genuïna és correcta?", "o": ["online – en línia", "e-mail – correu postal", "mouse – cursor"], "e": "Online: en línia. E-mail: correu electrònic; mouse: ratolí."},
      {"q": "Una imatge del que es veu en la pantalla en un moment determinat és...", "o": ["una captura de pantalla", "un fons de pantalla", "un protector de pantalla"], "e": "Captura de pantalla. El fons de pantalla és la imatge de l'escriptori."},
      {"q": "Tornar a engegar un ordinador després d'apagar-lo és...", "o": ["reiniciar-lo", "reinstal·lar-lo", "desinstal·lar-lo"], "e": "Reiniciar. Reinstal·lar és tornar a instal·lar un programa."},
      {"q": "Instal·lar la versió més recent d'un programa és...", "o": ["actualitzar-lo", "desinstal·lar-lo", "configurar-lo"], "e": "Actualitzar (una actualització)."},
      {"q": "Identificar-se amb el nom d'usuari i la contrasenya per a entrar en un servici és...", "o": ["iniciar la sessió", "tancar la sessió", "donar-se de baixa"], "e": "Iniciar la sessió. En acabar, cal tancar-la."},
      {"q": "Un conjunt de dades emmagatzemades de manera organitzada perquè es puguen consultar fàcilment és...", "o": ["una base de dades", "un fons de pantalla", "un full de ruta"], "e": "Base de dades."},
      {"q": "Un programa que detecta i elimina els programes maliciosos és...", "o": ["un antivirus", "un navegador", "un processador de textos"], "e": "Antivirus."},
      {"q": "La peça de l'ordinador que executa les instruccions dels programes és...", "o": ["el processador", "el monitor", "l'altaveu"], "e": "El processador."},
      {"q": "Quina expressió és correcta?", "o": ["Fes clic en la icona.", "Pincha en el icono.", "Fes clic en el icono."], "e": "Fer clic en la icona. «Icono» i «pinchar» són castellanismes."},
      {"q": "L'aparell que convertix un document en paper en un fitxer digital és...", "o": ["l'escàner", "la impressora", "el projector"], "e": "L'escàner (escanejar)."},
      {"q": "El conjunt de pàgines web d'una mateixa entitat, amb una adreça comuna, és...", "o": ["un lloc web", "un cercador", "un navegador"], "e": "Un lloc web (o web). El cercador busca pàgines."},
      {"q": "Quina frase és més adequada en un text formal?", "o": ["Adjunte el currículum a este correu electrònic.", "Adjunte el currículum a este mail.", "Adjunte el currículum a este emilio."], "e": "Correu electrònic. «Mail» és un anglicisme i «emilio», un col·loquialisme castellà."},
      {"q": "Quin verb és correcte per a conservar els canvis d'un document en l'ordinador?", "o": ["guardar (o desar)", "salvar", "estalviar"], "e": "Guardar o desar un document. «Salvar» és un calc de l'anglés save."},
      {"q": "La unitat mínima d'informació, que pot prendre el valor 0 o 1, és...", "o": ["el bit", "el píxel", "el codi"], "e": "El bit."},
      {"q": "Cada un dels punts que formen una imatge digital és...", "o": ["un píxel", "un bit", "un vèrtex"], "e": "Un píxel. Com més píxels, més resolució."},
      {"q": "Les instruccions d'un programa escrites en un llenguatge de programació formen el codi...", "o": ["font", "base", "origen"], "e": "Codi font."},
      {"q": "Escriu la forma genuïna de l'anglicisme «spam» (dues paraules).", "a": ["correu brossa", "el correu brossa"], "e": "Correu brossa: correu no sol·licitat i enviat massivament."},
      {"q": "Escriu la forma genuïna de l'anglicisme «software».", "a": ["programari", "el programari"], "e": "Programari (i maquinari per a «hardware»)."},
      {"q": "Escriu el nom del símbol @.", "a": ["arrova", "l'arrova"], "e": "L'arrova, amb v."},
      {"q": "Escriu la forma genuïna de «hacker» (dues paraules: pirata ___).", "a": ["pirata informàtic", "informàtic"], "e": "Pirata informàtic."},
      {"q": "Escriu la paraula que falta: «Fes una còpia de ___ dels fitxers» (angl. backup).", "a": ["seguretat"], "e": "Còpia de seguretat."},
      {"q": "Escriu el verb genuí, propi del valencià, per a «pegar» un text copiat (comença per a-).", "a": ["apegar"], "e": "Apegar (o enganxar): copiar i apegar."},
      {"q": "Escriu el nom del programa que servix per a visitar pàgines web (comença per n-).", "a": ["navegador", "el navegador"], "e": "El navegador (navegar)."},
      {"q": "Escriu el nom de la protecció de les dades i de la vida íntima (comença per p-).", "a": ["privadesa", "la privadesa"], "e": "La privadesa."},
      {"q": "Escriu la forma genuïna de «llamada» telefònica que comença per t-.", "a": ["telefonada", "una telefonada", "trucada", "una trucada"], "e": "Telefonada (o trucada, cridada)."}
    ]
  },
  {
    "id": "c5314269-b953-5723-9686-d3b6fe160aca", "type": "c1_lex_fraseologia", "sort_order": 13,
    "title": "Fraseologia: frases fetes, locucions i refranys", "name": "Expressions idiomàtiques d'ús freqüent, refranys i formes genuïnes davant dels calcs fraseològics",
    "content": "Les expressions idiomàtiques i els enunciats fraseològics d'ús freqüent: frases fetes i locucions (verbals i adverbials) amb el seu significat figurat, refranys tradicionals i el seu sentit, i les formes genuïnes que cal preferir davant dels calcs de la fraseologia castellana (3.2.3).", "icon": "🗣️", "color": "#E1BEE7",
    "exercises": [
      {"q": "«Quan li vaig demanar explicacions, es va fer l'orni.» Què va fer?", "o": ["Va fer veure que no sabia res del tema", "Es va enfadar moltíssim", "Va demanar perdó de seguida"], "e": "Fer-se l'orni: fer-se el desentés, fer veure que no se sap o no s'entén una cosa (com fer-se el suec)."},
      {"q": "«Sense finançament, el projecte se'n va anar en orris.» Què li va passar?", "o": ["Va fracassar", "Es va acabar amb èxit", "Es va ajornar uns mesos"], "e": "Anar-se'n en orris: fracassar, malbaratar-se una cosa."},
      {"q": "«No busques tres peus al gat: el contracte és ben clar.» Què li diuen?", "o": ["Que no complique una cosa que és senzilla", "Que no perda el temps amb animals", "Que no busque el culpable"], "e": "Buscar tres peus al gat: buscar complicacions o problemes on no n'hi ha."},
      {"q": "«Abans de signar, vull posar els punts sobre les is.» Què vol fer?", "o": ["Aclarir les coses amb precisió, sense ambigüitats", "Corregir les faltes d'ortografia", "Signar només amb les inicials"], "e": "Posar els punts sobre les is: precisar i aclarir una qüestió perquè no hi haja malentesos."},
      {"q": "«No et fiques en camisa d'onze vares.» Quin consell li donen?", "o": ["Que no s'embolique en assumptes que no li pertoquen o que el superen", "Que no es pose roba massa gran", "Que no gaste més del compte en la boda"], "e": "Ficar-se en camisa d'onze vares: embolicar-se en una cosa complicada o que no ens correspon."},
      {"q": "«Per fi ha caigut de la figuera: ara sap que l'enganyaven.» Què li ha passat?", "o": ["S'ha adonat de la realitat i ha deixat de ser ingenu", "S'ha fet mal en una caiguda", "S'ha distret i ho ha oblidat tot"], "e": "Caure de la figuera: adonar-se d'una cosa que tothom ja sabia, deixar de ser ingenu."},
      {"q": "«Quan li van dir que no hi havia plaça, es va quedar amb un pam de nas.» Com es va quedar?", "o": ["Decebut, amb les esperances frustrades", "Molt content i satisfet", "Indiferent, sense cap reacció"], "e": "Quedar-se amb un pam de nas: quedar-se decebut, burlat en les seues expectatives."},
      {"q": "«En unes negociacions tan delicades cal anar amb peus de plom.» Com cal actuar?", "o": ["Amb molta prudència", "Amb rapidesa i decisió", "Amb fermesa, sense cedir en res"], "e": "Anar amb peus de plom: actuar amb molta cautela i prudència."},
      {"q": "«No vaig poder anar a l'assemblea: fes-me'n cinc cèntims.» Què li demana?", "o": ["Que li ho explique breument", "Que li deixe uns diners", "Que li faça un descompte"], "e": "Fer cinc cèntims d'una cosa: explicar-la de manera resumida."},
      {"q": "«Aprovar les oposicions li ha costat Déu i ajuda.» Què vol dir?", "o": ["Que li ha costat moltíssim d'esforç", "Que li ha costat molts diners", "Que no li ha costat gens"], "e": "Costar Déu i ajuda: costar molt d'esforç o de treball."},
      {"q": "«Per a una enginyera com ella, això és bufar i fer ampolles.» Com és la tasca?", "o": ["Molt fàcil", "Molt difícil", "Molt perillosa"], "e": "Ser bufar i fer ampolles: ser molt fàcil. Calc que cal evitar: «ser pa menjat»."},
      {"q": "«Des que va arribar, el nou cap no para de fer-me la guitza.» Què fa?", "o": ["Molestar-me i posar-me entrebancs", "Fer-me favors contínuament", "Felicitar-me per la feina"], "e": "Fer la guitza: molestar, importunar, posar dificultats a algú."},
      {"q": "«En tota la sessió no va badar boca.» Què va fer?", "o": ["No va dir res", "No va parar de parlar", "Va badallar de son"], "e": "No badar boca: no dir ni una paraula."},
      {"q": "«En aquella botiga ens van donar gat per llebre.» Què va passar?", "o": ["Ens van enganyar donant-nos una cosa de menys valor", "Ens van regalar una mascota", "Ens van canviar el producte per un de millor"], "e": "Donar gat per llebre: enganyar fent passar una cosa per una altra de més valor."},
      {"q": "«La casa rural està a la quinta forca.» On està?", "o": ["Molt lluny, en un lloc apartat", "Molt a prop del poble", "Dalt d'un turó"], "e": "A la quinta forca: molt lluny."},
      {"q": "«Va acceptar el trasllat a contracor.» Com el va acceptar?", "o": ["Sense voler-ho, contra la seua voluntat", "Amb entusiasme", "Sense pensar-s'ho"], "e": "A contracor: a desgrat, de mala gana. Equival al castellà «a regañadientes»."},
      {"q": "«Mentre parlava, el jutge la mirava de reüll.» Com la mirava?", "o": ["De costat, dissimuladament, sense girar el cap", "Fixament i de cara", "Amb els ulls tancats"], "e": "Mirar de reüll: mirar de gairell, sense girar el cap, amb desconfiança o dissimulació."},
      {"q": "«No va ser un accident: va trencar el vidre a gratcient.» Com el va trencar?", "o": ["Expressament, amb plena consciència", "Sense voler", "Per pura casualitat"], "e": "A gratcient: deliberadament, sabent el que es fa."},
      {"q": "«És una edició de pa sucat amb oli.» Com és l'edició?", "o": ["De poca qualitat, feta amb pocs mitjans", "Luxosa i molt cuidada", "Dedicada a la cuina tradicional"], "e": "De pa sucat amb oli: de poca categoria, pobre, mal fet."},
      {"q": "«En l'empresa, qui té la paella pel mànec és el soci majoritari.» Què vol dir?", "o": ["Que és qui té el control i pren les decisions", "Que és qui cuina en les celebracions", "Que està a punt de deixar l'empresa"], "e": "Tindre la paella pel mànec: tindre el control d'una situació."},
      {"q": "«Quan va tastar el vi, va fer cara de pomes agres.» Quina cara va fer?", "o": ["De disgust o de desaprovació", "D'alegria", "De sorpresa agradable"], "e": "Fer cara de pomes agres: mostrar disgust, enuig o desaprovació en el gest."},
      {"q": "Quina d'estes unitats fraseològiques és un refrany (un enunciat sentenciós i complet)?", "o": ["Qui dia passa, any empeny.", "fer-se l'orni", "a la quinta forca"], "e": "El refrany és un enunciat complet amb valor de sentència. Fer-se l'orni és una locució verbal i a la quinta forca, una locució adverbial."},
      {"q": "Quina d'estes expressions és una locució adverbial?", "o": ["de reüll", "Per la boca mor el peix.", "fer la guitza"], "e": "De reüll modifica un verb com un adverbi (mirar de reüll). Fer la guitza és una locució verbal; l'altra és un refrany."},
      {"q": "«De mica en mica s'ompli la pica.» Què ensenya este refrany?", "o": ["Que amb constància i a poc a poc s'aconseguixen les coses", "Que cal estalviar aigua", "Que les coses fetes de pressa ixen malament"], "e": "Els resultats s'obtenen amb esforç continuat i gradual."},
      {"q": "«Per la boca mor el peix.» Què vol dir?", "o": ["Que parlar més del compte pot perjudicar qui parla", "Que cal menjar amb moderació", "Que els pescadors han de callar"], "e": "Qui parla massa acaba descobrint el que hauria de callar."},
      {"q": "«Qui no vulga pols, que no vaja a l'era.» Quin és el sentit del refrany?", "o": ["Qui no vol patir les conseqüències d'una cosa, que no s'hi fique", "Que cal netejar bé la casa", "Que el treball del camp és molt dur"], "e": "Si no vols els inconvenients d'una situació, no t'hi poses."},
      {"q": "«A cada porc li arriba el seu sant Martí.» Què expressa?", "o": ["Que tard o d'hora tothom rep el que es mereix", "Que les festes arriben cada any", "Que cal ajudar els altres"], "e": "Tard o d'hora, qui obra malament en paga les conseqüències."},
      {"q": "«Gat escaldat, de l'aigua freda fuig.» Què vol dir?", "o": ["Que qui ha tingut una mala experiència es torna desconfiat", "Que els gats no volen banyar-se", "Que cal fugir dels perills imaginaris"], "e": "La mala experiència fa ser previngut fins i tot davant del que no és perillós."},
      {"q": "«No per molt matinar, fa més prompte de dia.» Què ensenya?", "o": ["Que les coses tenen el seu temps i no s'avancen per més que ens afanyem", "Que cal alçar-se prompte cada dia", "Que l'hivern té els dies més curts"], "e": "L'excés de pressa no fa arribar abans els resultats."},
      {"q": "«Qui no té faena, el gat pentina.» De qui es parla?", "o": ["De qui, per no tindre res a fer, s'entreté en coses inútils", "De qui cuida bé els animals", "De qui treballa en una perruqueria"], "e": "Es diu de qui ocupa el temps en activitats supèrflues."},
      {"q": "«Del dit al fet hi ha un bon tros.» Què vol dir?", "o": ["Que és més fàcil dir les coses que fer-les", "Que cal mesurar bé les distàncies", "Que els fets valen menys que les paraules"], "e": "Hi ha molta diferència entre prometre una cosa i complir-la."},
      {"q": "Quina és la forma genuïna de l'expressió castellana «de golpe y porrazo»?", "o": ["de colp i volta", "de colp i porrada", "de colp i porrassa"], "e": "De colp i volta: de sobte, sense avís."},
      {"q": "Quina és la forma genuïna de «llevar a cabo» un projecte?", "o": ["dur a terme un projecte", "portar a cap un projecte", "dur a cabo un projecte"], "e": "Dur (o portar) a terme. «Portar a cap» és un calc."},
      {"q": "Quina és la forma genuïna de «pagar el pato»?", "o": ["pagar els plats trencats", "pagar l'ànec", "pagar el pato"], "e": "Pagar els plats trencats: patir les conseqüències d'una cosa de què no s'és responsable."},
      {"q": "Quina és la forma genuïna de «a ojo de buen cubero»?", "o": ["a ull", "a ull de bon cuber", "a bon ull de cubero"], "e": "A ull: aproximadament, sense mesurar. «Calcular a ull»."},
      {"q": "Quina és la forma genuïna de «sin ton ni son»?", "o": ["sense solta ni volta", "sense to ni so", "sense ton ni son"], "e": "Sense solta ni volta: sense sentit, sense raó."},
      {"q": "Quina és la forma genuïna de «ni mucho menos»?", "o": ["ni de bon tros", "ni molt menys", "ni de molt menys"], "e": "Ni de bon tros: de cap manera, ni de lluny. «No ha acabat, ni de bon tros»."},
      {"q": "Quina és la forma genuïna de «a duras penas»?", "o": ["amb prou faenes", "a dures penes", "a penes dures"], "e": "Amb prou faenes (o a penes): amb molta dificultat, quasi no."},
      {"q": "Completa el refrany: «Qui sembra vents, cull ___.»", "a": ["tempestats"], "e": "Qui provoca conflictes acaba patint-ne conseqüències pitjors."},
      {"q": "Completa el refrany: «No digues blat fins que no estiga al sac i ben ___.»", "a": ["lligat"], "e": "No cal donar per fet un resultat fins que no estiga assegurat."},
      {"q": "Completa el refrany: «En terra de cecs, el ___ és el rei.»", "a": ["borni"], "e": "Entre persones poc capacitades, qui en sap una mica destaca."},
      {"q": "Completa el refrany: «Més val pardal en mà que cent ___.»", "a": ["volant"], "e": "Més val una cosa segura, encara que siga poca, que moltes d'incertes."},
      {"q": "Completa la locució que vol dir 'embolicar-se en assumptes complicats': «ficar-se en camisa d'___ vares».", "a": ["onze"], "e": "Ficar-se en camisa d'onze vares."},
      {"q": "Completa la locució que vol dir 'buscar complicacions innecessàries': «buscar tres peus al ___».", "a": ["gat"], "e": "Buscar tres peus al gat."},
      {"q": "Completa l'expressió que vol dir 'en un instant': «en un tancar i obrir d'___».", "a": ["ulls"], "e": "En un tancar i obrir d'ulls: en un moment, molt ràpidament."}
    ]
  },
  {
    "id": "8ffa1610-0e6e-5dda-a285-448e9f096324", "type": "c1_lex_derivacio", "sort_order": 14,
    "title": "Derivació: afixos i significat", "name": "Sufixos d'arbres, conjunts, mesures, qualitats, accions, tendències i doctrines; diminutius, augmentatius, pejoratius i oficis",
    "content": "La derivació des del punt de vista morfològic i semàntic: els afixos usuals i el seu significat; els sufixos valoratius (diminutius, augmentatius i pejoratius), els noms d'oficis i d'agents, i els sufixos que designen plantes i arbres, conjunts, dimensions i mesures, qualitats, estats, accions i efectes, tendències, i doctrines i ideologies (-isme, -ista), a més de la parasíntesi i la conversió, segons la GNV (3.2.3).", "icon": "🌳", "color": "#C8E6C9",
    "exercises": [
      {"q": "Quin sufix forma noms d'arbres i de plantes a partir del nom del fruit (taronja > taronger, figa > figuera)?", "o": ["-er / -era", "-eda / -ar", "-ari / -ària"], "e": "Taronger, ametler, albercoquer; figuera, pomera, fesolera. -eda i -ar indiquen el lloc poblat d'una espècie."},
      {"q": "La planta que fa tomaques és...", "o": ["la tomaquera", "la tomaquària", "la tomaqueda"], "e": "Tomaca > tomaquera, com fesol > fesolera o carabassa > carabassera."},
      {"q": "Quin d'estos noms designa un arbre i no un conjunt d'arbres?", "o": ["el garrofer", "la pineda", "l'alzinar"], "e": "Garrofa > garrofer (-er: arbre). Pineda i alzinar (-eda, -ar) designen llocs poblats d'una espècie."},
      {"q": "Quin sufix indica un conjunt d'arbres o un lloc poblat d'una espècie en «pineda», «fageda» i «roureda»?", "o": ["-eda", "-era", "-ària"], "e": "-eda forma col·lectius vegetals: pineda (pins), fageda (faigs), roureda (roures)."},
      {"q": "Un bosc de faigs és...", "o": ["una fageda", "una faiguera", "un faigatge"], "e": "Faig + -eda > fageda."},
      {"q": "Un terreny poblat d'alzines és...", "o": ["un alzinar", "una alzinària", "un alzinatge"], "e": "El sufix -ar també forma col·lectius de plantes: alzinar, canyar."},
      {"q": "El conjunt de les plomes d'un ocell és...", "o": ["el plomatge", "la plomada", "el plomer"], "e": "-atge té valor col·lectiu: plomatge, fullatge, veïnatge."},
      {"q": "Quin és el nom col·lectiu que designa el conjunt dels professors d'un centre?", "o": ["el professorat", "la professoria", "el professoratge"], "e": "-at col·lectiu: professorat, alumnat, voluntariat."},
      {"q": "Quin sufix forma noms de dimensió com «fondària», «llargària» o «amplària»?", "o": ["-ària", "-eria", "-ança"], "e": "-ària designa dimensions: fondària, llargària, amplària, grandària, alçària."},
      {"q": "La dimensió vertical d'un pou, des de la boca fins al fons, és...", "o": ["la fondària", "la fonderia", "la fondència"], "e": "Fondo + -ària > fondària."},
      {"q": "En «palada», «carretada» o «cabassada», el sufix -ada indica...", "o": ["la quantitat que cap en un recipient o instrument", "un colp donat amb l'objecte", "un lloc ple d'eixos objectes"], "e": "-ada de mesura: la quantitat que cap en una pala, un carro o un cabàs."},
      {"q": "En «ganivetada», «pedrada» o «puntada», el sufix -ada indica...", "o": ["un colp o una ferida feta amb l'objecte", "la quantitat que cap en l'objecte", "un conjunt d'objectes"], "e": "-ada també expressa colp: ganivetada, pedrada, puntada (de peu)."},
      {"q": "Quina sèrie conté només noms de qualitat?", "o": ["dolçor, bellesa, valentia, avarícia", "dolçor, cullerada, pineda, plomatge", "bellesa, bibliotecari, menjador, fregall"], "e": "-or, -esa, -ia i -ícia formen noms de qualitat a partir d'adjectius."},
      {"q": "Segons la GNV, quina variant del sufix -esa és pròpia del valencià central i meridional?", "o": ["-ea (pobrea, vellea)", "-essa (pobressa, vellessa)", "-eça (pobreça, velleça)"], "e": "El sufix -esa té la variant -ea des dels orígens: pobresa o pobrea, vellesa o vellea."},
      {"q": "La qualitat de qui és cortés és...", "o": ["la cortesia", "la cortesitat", "la corteseria"], "e": "Cortés > cortesia, com valent > valentia."},
      {"q": "Quin és el derivat en -ment del verb «nàixer»?", "o": ["naixement o naiximent (les dues formes són correctes)", "només naixement", "només naiximent"], "e": "Els derivats en -ment de verbs en -xer admeten les dues formes: naixement o naiximent, creixement o creiximent."},
      {"q": "Quin significat aporten -ció, -ment, -nça i -atge en «publicació», «nomenament», «assegurança» i «muntatge»?", "o": ["acció o efecte de l'acció del verb", "qualitat de l'adjectiu de base", "lloc on es fa l'acció"], "e": "Són sufixos deverbals que formen noms d'acció o d'efecte."},
      {"q": "Un «esvaró» és...", "o": ["una relliscada", "un esvaïment", "un vent fort"], "e": "Esvarar > esvaró, amb el sufix -ó d'acció o efecte, com espentar > espentó."},
      {"q": "En quina paraula el sufix -dor indica un lloc?", "o": ["menjador", "colador", "nedador"], "e": "Menjador: lloc on es menja. Colador és un instrument i nedador, un agent."},
      {"q": "L'utensili per a fregar els plats és...", "o": ["el fregall", "el fregatge", "el freguet"], "e": "-all forma noms d'instrument: fregall, ventall."},
      {"q": "Quin adjectiu indica tendència (‘que s'emmalaltix amb facilitat’)?", "o": ["malaltís", "malaltós", "malaltenc"], "e": "-ís / -issa expressa tendència: malaltís, malaltissa."},
      {"q": "Un material que es trenca amb molta facilitat és...", "o": ["trencadís", "trencador", "trencós"], "e": "-dís / -dissa indica tendència: trencadís, movedís, espantadís."},
      {"q": "En «comunisme», «humanisme» o «impressionisme», el sufix -isme indica...", "o": ["un corrent, una doctrina o un moviment", "una qualitat física", "un lloc o un establiment"], "e": "-isme: corrent, doctrina o ideologia. -ista: qui la seguix (comunista, humanista)."},
      {"q": "En «castellanisme», «gal·licisme» o «anglicisme», el sufix -isme indica...", "o": ["un mot o un tret lingüístic procedent d'una altra llengua", "una doctrina política", "una malaltia"], "e": "-isme també designa trets lingüístics: un castellanisme és un mot pres del castellà."},
      {"q": "En registres formals, com s'usa majoritàriament el sufix -ista?", "o": ["invariable: el periodista, la periodista", "amb -iste en masculí: el periodiste", "amb -isto en masculí: el periodisto"], "e": "La GNV admet la variació -iste/-ista, però en els registres formals -ista s'usa majoritàriament invariable."},
      {"q": "Qui ven claus, panys i eines en una botiga és...", "o": ["el ferreter", "el ferrer", "el ferrador"], "e": "Ferreter: qui ven articles de ferreteria. El ferrer forja el ferro i el ferrador posa ferradures."},
      {"q": "Qui compra i ven draps i objectes vells és...", "o": ["el drapaire", "el drapista", "el drapater"], "e": "-aire forma noms d'ofici: drapaire, guixaire."},
      {"q": "L'oficina on es fan els tràmits administratius d'un centre és...", "o": ["la secretaria", "la secretària", "la secretareria"], "e": "Secretaria (-ia): oficina o càrrec. Secretària: la persona que exercix el càrrec."},
      {"q": "Quina sèrie conté només sufixos diminutius?", "o": ["-et, -ó, -ic, -ell", "-às, -ot, -arro, -assa", "-astre, -or, -esa, -ia"], "e": "Cotxet, carreró, pobric, taulell. -às, -ot i -arro són augmentatius."},
      {"q": "En quina paraula el sufix diminutiu s'ha lexicalitzat i ja no indica grandària?", "o": ["sabatilla", "gatet", "caseta"], "e": "Una sabatilla no és una sabata menuda: és un calçat d'estar per casa. Altres lexicalitzats: pastilla, portella."},
      {"q": "Quin és l'augmentatiu de «mà»?", "o": ["manassa", "manàs", "maneta"], "e": "Mà (femení) > manassa, amb -às/-assa. Maneta és diminutiu."},
      {"q": "Un «animalot» és...", "o": ["un animal molt gros", "un animal molt menut", "un animal domèstic"], "e": "-ot/-ota és augmentatiu: animalot, grandota."},
      {"q": "Un «medicastre» és...", "o": ["un metge incompetent (despectiu)", "un metge molt prestigiós", "un estudiant de medicina"], "e": "-astre/-astra és despectiu: medicastre, politicastre."},
      {"q": "«Parlotejar» vol dir...", "o": ["parlar molt i de coses sense importància", "parlar en veu molt baixa", "parlar amb molta elegància"], "e": "El sufix -otejar dona un valor valoratiu al verb: parlotejar, manotejar."},
      {"q": "Quina paraula és un derivat parasintètic (prefix i sufix alhora)?", "o": ["empolsegar", "polsós", "polseta"], "e": "Em- + pols + -eg- + -ar: cal el prefix i el sufix alhora. Polsós i polseta només tenen sufix."},
      {"q": "El nom «guany» (de guanyar) s'ha format per...", "o": ["conversió o derivació zero", "sufixació", "composició"], "e": "Conversió: canvi de categoria sense sufix, com pescar > pesca o dubtar > dubte."},
      {"q": "Quin d'estos verbs deriva d'un adverbi?", "o": ["sovintejar", "gotejar", "groguejar"], "e": "Sovint > sovintejar. Gotejar ve d'un nom (gota) i groguejar d'un adjectiu (groc)."},
      {"q": "Escriu el nom de l'arbre que fa préssecs.", "a": ["presseguer", "el presseguer"], "e": "Préssec > presseguer (amb -er i gu davant de e)."},
      {"q": "Escriu el nom de l'arbre que fa figues.", "a": ["figuera", "la figuera"], "e": "Figa > figuera (-era)."},
      {"q": "Escriu el nom derivat (en -ada) que designa la quantitat que cap en una cullera.", "a": ["cullerada", "una cullerada"], "e": "Cullera > cullerada."},
      {"q": "Escriu el nom derivat de «grapa» que designa la quantitat que es pot agafar amb la mà: «un ___ d'ametles».", "a": ["grapat"], "e": "Un grapat: el que cap en la mà."},
      {"q": "Escriu el nom de qualitat derivat de «dolç» amb el sufix -or.", "a": ["dolçor", "la dolçor"], "e": "Dolç > dolçor, com blanc > blancor o fresc > frescor."},
      {"q": "Escriu l'adjectiu en -ut que vol dir 'que té banyes'.", "a": ["banyut"], "e": "-ut/-uda indica possessió: banyut, panxut, geperut."},
      {"q": "Completa amb un adjectiu en -dís: «Van quedar atrapats en unes arenes ___» (que es mouen).", "a": ["movedisses"], "e": "Moure > movedís, movedissa: que es mou amb facilitat."},
      {"q": "Escriu el nom (en -isme) del moviment que defensa la pau i rebutja la violència.", "a": ["pacifisme", "el pacifisme"], "e": "Pacifisme; qui el seguix és pacifista."}
    ]
  },
  {
    "id": "a3522a8d-bc85-5605-bfa8-511828d955ae", "type": "c1_lex_prefixacio_composicio", "sort_order": 15,
    "title": "Prefixació i composició", "name": "Prefixos cultes, el prefix no-, compostos patrimonials, expressius i amb punts cardinals; guionet o aglutinació",
    "content": "Els derivats per prefixació (arxiconegut, expresident, precristià, pseudofruit, subsecretària, vicerector, ultracongelació...) i l'ús del prefix no- amb guionet o sense (no-violència; comunicació no verbal), els compostos de dos elements amb significat ple (bocamoll, agredolç, centcames, gira-sol, cara-xuplat, penja-roba), els compostos expressius o reduplicatius (xano-xano, zig-zag) i els que contenen un punt cardinal (nord-est, sud-africana), amb la grafia aglutinada, amb guionet o separada que establixen la GNV i la GVB (3.2.3).", "icon": "🔗", "color": "#FFF9C4",
    "exercises": [
      {"q": "«Arxiconegut» vol dir...", "o": ["coneguíssim, molt conegut", "conegut només pels arxivers", "desconegut del tot"], "e": "Arxi- té valor intensiu davant d'adjectius (arxiconegut) i de rang superior davant de noms (arxiduc, arxidiòcesi)."},
      {"q": "En «arxiduc» i «arxidiòcesi», el prefix arxi- indica...", "o": ["superioritat de rang", "anterioritat en el temps", "negació"], "e": "Un arxiduc té un títol superior al de duc; una arxidiòcesi és una diòcesi principal."},
      {"q": "Com s'escriu el nom de qui ha deixat de ser president?", "o": ["expresident", "ex-president", "ex president"], "e": "Els derivats amb prefix s'escriuen aglutinats, sense guionet: expresident, exministre."},
      {"q": "Com s'escriu el prefix ex- davant de la locució «alt càrrec»?", "o": ["un ex alt càrrec", "un exalt càrrec", "un ex-alt càrrec"], "e": "Quan el prefix precedix una locució lexicalitzada, s'escriu separat: ex alt càrrec, vice primer ministre, pro drets humans."},
      {"q": "Una cultura «precristiana» és...", "o": ["anterior al cristianisme", "contrària al cristianisme", "posterior al cristianisme"], "e": "Pre- indica anterioritat: precristià, preromà, prehistòria."},
      {"q": "Què aporta el prefix pseudo- en «pseudofruit» o «pseudociència»?", "o": ["‘fals, aparent’", "‘molt gran’", "‘a mitjan camí’"], "e": "Una pseudociència té aparença de ciència sense ser-ho. S'escriu aglutinat: pseudofruit, pseudociència."},
      {"q": "Una «subsecretària» és...", "o": ["una persona amb un càrrec immediatament inferior al de secretària", "una secretària que treballa en un soterrani", "una exsecretària"], "e": "Sub- (i sots-) indiquen rang inferior: subsecretària, subdirector, sotsdelegat."},
      {"q": "Quina grafia és correcta?", "o": ["vicerector", "vicerrector", "vice-rector"], "e": "Després de determinats prefixos es manté la r simple: vicerector, semirecta, contrarestar (GVB)."},
      {"q": "Quina grafia és correcta?", "o": ["contrasenya", "contrassenya", "contra-senya"], "e": "Després de determinats prefixos es manté la s simple: contrasenya, antisocial, asimetria."},
      {"q": "Quina grafia és correcta?", "o": ["antiinflamatori", "antinflamatori", "anti-inflamatori"], "e": "El prefix s'unix a la base sense guionet i es manté la i de cada element: antiinflamatori."},
      {"q": "La «ultracongelació» és...", "o": ["la congelació ràpida a temperatures molt baixes", "la descongelació d'un aliment", "la congelació parcial"], "e": "Ultra- ‘més enllà, en grau extrem’: ultracongelació, ultramodern, ultratomba."},
      {"q": "Una injecció «intravenosa» es posa...", "o": ["dins de la vena", "entre dues venes", "per damunt de la vena"], "e": "Intra- ‘dins de’ (intravenós, intracel·lular); inter- ‘entre’ (interacció)."},
      {"q": "«Infravalorar» vol dir...", "o": ["valorar per davall del que val realment", "valorar de nou", "valorar amb exageració"], "e": "Infra- ‘per davall de’. El contrari és sobrevalorar."},
      {"q": "L'«avantbraç» és...", "o": ["la part del braç entre el colze i el canell", "la part del braç entre l'espatla i el colze", "el braç esquerre"], "e": "Avant- ‘davant, abans’: avantbraç."},
      {"q": "Per què s'escriu separat «pre ocupació» (‘abans de l'ocupació’)?", "o": ["Per a evitar la confusió amb «preocupació»", "Perquè pre- sempre s'escriu separat", "Perquè ocupació comença per vocal"], "e": "Si la unió pot crear formes homònimes, el prefix s'escriu separat: pre ocupació, ex pres."},
