      {"q": "«Bocamoll» té la mateixa estructura (nom + adjectiu) que...", "o": ["camallarg", "torcamans", "malhumor"], "e": "Boca + moll, cama + llarg. Torcamans és verb + nom i malhumor, adjectiu + nom."},
      {"q": "Un «centcames» és...", "o": ["un animal invertebrat amb moltes potes", "un moble de molts peus", "una mesura de longitud"], "e": "Centcames: quantificador + nom, escrit aglutinat."},
      {"q": "Quina grafia és correcta?", "o": ["cara-xuplat", "caraxuplat", "cara xuplat"], "e": "Porta guionet perquè el primer element acaba en vocal i el segon comença per x-."},
      {"q": "Quina grafia és correcta per al moble on es penja la roba?", "o": ["penja-roba", "penjaroba", "penja roba"], "e": "Guionet: el primer element acaba en vocal i el segon comença per r- (com gira-sol, para-xocs)."},
      {"q": "Per què s'escriu «pit-roig» amb guionet?", "o": ["Perquè, aglutinat, les lletres en contacte en dificultarien la lectura", "Perquè és un nom d'ocell", "Perquè el primer element porta accent"], "e": "Guionet quan l'aglutinació pot alterar la lectura: pit-roig, cor-robat, Bell-lloc."},
      {"q": "Per què s'escriu «mà-llarg» amb guionet?", "o": ["Perquè el primer element és patrimonial i porta accent gràfic", "Perquè el segon element comença per ll-", "Perquè és un adjectiu"], "e": "Compostos patrimonials amb el primer element accentuat: mà-llarg, pèl-roig, despús-ahir."},
      {"q": "Quin d'estos compostos està ben escrit aglutinat, sense guionet?", "o": ["trencaanous", "girasol", "parasol"], "e": "Com a norma general, els compostos s'escriuen aglutinats (trencaanous, pocavergonya, allioli), però gira-sol i para-sol duen guionet (s- després de vocal)."},
      {"q": "Quina grafia és correcta?", "o": ["usdefruit", "ús-de-fruit", "úsdefruit"], "e": "Usdefruit s'escriu sense guionet i sense accent, per tindre una grafia molt consolidada."},
      {"q": "«Arrancar un mal hàbit de soca-rel» vol dir...", "o": ["eliminar-lo completament, des de l'arrel", "eliminar-lo a poc a poc", "eliminar-lo només en part"], "e": "De soca-rel: de l'arrel, totalment. Duu guionet perquè el segon element comença per r-."},
      {"q": "«Donar el vistiplau a un projecte» vol dir...", "o": ["aprovar-lo", "revisar-lo per primera vegada", "rebutjar-lo"], "e": "Vistiplau: compost de dos verbs coordinats (vist i plau), com vaivé."},
