      {"q": "Les varietats funcionals (registres) depenen de...", "o": ["la situació comunicativa: el tema, el canal, la relació entre els interlocutors i la intenció", "el lloc de naixement del parlant", "l'època en què es va escriure el text"], "e": "Un mateix parlant canvia de registre segons la situació."},
      {"q": "La preposició «ab» (per «amb») dels textos medievals és...", "o": ["una forma de la varietat històrica (llengua antiga)", "un vulgarisme actual", "un castellanisme"], "e": "És una forma antiga que la llengua actual ha substituït per «amb»."},
      {"q": "Els dos grans blocs dialectals de la llengua són...", "o": ["l'oriental i l'occidental", "el septentrional i el meridional", "el continental i l'insular"], "e": "El bloc occidental inclou el valencià i el nord-occidental; l'oriental, el central, el balear, el rossellonés i l'alguerés."},
      {"q": "El valencià pertany al bloc...", "o": ["occidental, amb el nord-occidental", "oriental, amb el balear", "insular, amb l'alguerés"], "e": "El valencià i el nord-occidental formen el bloc occidental."},
      {"q": "Quin d'estos dialectes pertany al bloc oriental?", "o": ["el balear", "el valencià", "el nord-occidental"], "e": "El bloc oriental: central, balear, rossellonés i alguerés."},
      {"q": "Una característica del bloc occidental, que inclou el valencià, és...", "o": ["que distingix la a i la e àtones (pare, porta)", "que pronuncia la a i la e àtones amb vocal neutra", "que usa l'article salat"], "e": "En el bloc oriental, la a i la e àtones es confonen en una vocal neutra."},
      {"q": "L'article salat («es cotxe», «sa casa») és característic...", "o": ["del balear", "del valencià meridional", "de l'alguerés"], "e": "L'article salat és una marca del balear (i d'alguns punts de la costa catalana)."},
      {"q": "La primera persona del present «jo parle» és pròpia...", "o": ["del valencià", "del balear", "del central"], "e": "Valencià: parle; central: parlo; balear: parl."},
      {"q": "Quins són els subdialectes del valencià?", "o": ["el de transició (tortosí), el septentrional, el central (apitxat), el meridional i l'alacantí", "el balear, l'alguerés i el rossellonés", "el nord-occidental i el central"], "e": "Són les varietats del valencià de nord a sud."},
      {"q": "Les formes «hui», «eixir», «espill» o «xiquet» són...", "o": ["marques geogràfiques del valencià, totes normatives", "formes col·loquials no admeses en registre formal", "formes de la llengua antiga"], "e": "Són formes pròpies del valencià i adequades en qualsevol registre."},
      {"q": "Quina afirmació sobre el valencià estàndard és correcta?", "o": ["Admet les formes pròpies del valencià, com «este», «servix» o «tindre», en tots els registres", "Només admet les formes del català central", "No admet les formes valencianes en els textos formals"], "e": "L'estàndard valencià integra les formes genuïnes del territori."},
      {"q": "Els demostratius «este / eixe / aquell» corresponen al sistema...", "o": ["de tres graus, propi del valencià", "de dos graus, propi del central", "de la llengua antiga"], "e": "El valencià distingix tres graus de proximitat; el central en té dos (aquest / aquell)."},
      {"q": "«Vosté» i «vostè»...", "o": ["són variants geogràfiques normatives: la primera és la valenciana", "la primera és un vulgarisme", "són dos pronoms diferents"], "e": "El valencià pronuncia la e tancada i l'escriu amb accent tancat: vosté."},
      {"q": "Com s'anomena la varietat que usen els metges, els advocats o els informàtics quan parlen de la seua especialitat?", "o": ["llenguatge d'especialitat", "argot juvenil", "dialecte"], "e": "Els llenguatges d'especialitat tenen una terminologia pròpia i precisa."},
      {"q": "El tenor d'una situació comunicativa fa referència a...", "o": ["la relació entre els interlocutors i el grau de formalitat", "el tema del text", "el canal oral o escrit"], "e": "El camp és el tema; el mode, el canal; el tenor, la relació entre els interlocutors."},
      {"q": "«Ostres, quina calor fa hui!» Quin registre és?", "o": ["col·loquial", "formal", "especialitzat"], "e": "La interjecció i l'exclamació espontània són pròpies del registre col·loquial."},
      {"q": "«El pacient presenta hipertensió arterial i taquicàrdia.» Quin registre és?", "o": ["especialitzat (mèdic)", "col·loquial", "vulgar"], "e": "La terminologia tècnica és pròpia del llenguatge d'especialitat."},
      {"q": "«Per mitjà del present escrit, sol·licite que se'm concedisca l'ajuda.» Quin registre és?", "o": ["formal administratiu", "col·loquial", "literari"], "e": "Fórmules fixades com «per mitjà del present escrit» són pròpies dels documents administratius."},
      {"q": "Quina fórmula és adequada per a acabar una carta formal?", "o": ["Atentament,", "Una abraçada ben forta,", "Fins després!"], "e": "«Atentament» és la fórmula de comiat habitual en la correspondència formal."},
      {"q": "En un text formal, quina frase és adequada?", "o": ["Ens n'anem a les deu.", "Mos n'anem a les deu.", "Mos anem a les deu."], "e": "«Mos» és una forma col·loquial; en registre formal cal usar «ens»."},
      {"q": "Quina frase és més adequada en una conferència acadèmica?", "o": ["Cal destacar que els resultats confirmen la hipòtesi inicial.", "Mireu, la cosa és que els resultats van bé.", "Bé, pos això, que la hipòtesi funciona."], "e": "El registre formal demana precisió lèxica i evitar comodins com «la cosa»."},
      {"q": "En una conversa entre amics, quina frase és adequada?", "o": ["Quedem a les huit al bar de sempre?", "Us convoquem a les vint hores al local habitual.", "Es prega l'assistència a les vint hores."], "e": "Un registre massa formal és inadequat en una situació familiar."},
      {"q": "Quin terme jurídic designa la resolució d'un jutge que posa fi a un judici?", "o": ["sentència", "instància", "denúncia"], "e": "La sentència resol el judici; la instància és una sol·licitud i la denúncia inicia un procediment."},
      {"q": "Què és la varietat estàndard?", "o": ["la varietat formal comuna, fixada per la normativa, que servix per als usos públics", "la varietat parlada en la capital", "la varietat més antiga de la llengua"], "e": "L'estàndard s'usa en l'ensenyament, l'administració i els mitjans de comunicació."},
      {"q": "Les Normes de Castelló, que van fixar les bases de l'ortografia comuna, es van signar l'any...", "o": ["1932", "1906", "1998"], "e": "El 1906 es va fer el Primer Congrés Internacional de la Llengua; el 1998 es va aprovar la llei de creació de l'AVL."},
      {"q": "Quina institució establix la normativa del valencià?", "o": ["l'Acadèmia Valenciana de la Llengua (AVL)", "la Junta Qualificadora de Coneixements de Valencià", "la Conselleria d'Educació"], "e": "La Junta Qualificadora certifica el coneixement de la llengua; la normativa la fixa l'AVL."},
      {"q": "El Segle d'Or de les lletres valencianes correspon al segle...", "o": ["XV", "XIX", "XII"], "e": "És l'època d'Ausiàs March, Joanot Martorell o Isabel de Villena."},
      {"q": "Quina parella mostra la variació geogràfica en el lèxic?", "o": ["xiquet (valencià) / al·lot (balear)", "xiquet / xiqueta", "xiquet / xiquetet"], "e": "Són dues formes de territoris diferents per al mateix concepte."},
      {"q": "Un parlant canvia la manera de parlar segons si està en una entrevista de treball o amb la família. Quina variació mostra?", "o": ["variació funcional (de registre)", "variació geogràfica", "variació històrica"], "e": "El registre s'adapta a la situació comunicativa."},
      {"q": "En quina situació és adequat un registre col·loquial?", "o": ["Una conversa per telèfon amb un germà", "Una sol·licitud a l'ajuntament", "Un article científic"], "e": "El registre col·loquial és propi de les relacions de confiança."},
      {"q": "Quina forma verbal és pròpia del valencià?", "o": ["servix", "serveixo", "servesc"], "e": "Servix és la forma valenciana; serveixo és pròpia del central i servesc, del balear."},
      {"q": "Escriu el nom del registre propi de la conversa espontània i familiar: c___", "a": ["col·loquial"], "e": "El registre col·loquial s'oposa al formal."},
      {"q": "Escriu el nom del subdialecte del valencià parlat a València i a l'Horta, que no distingix les sibilants sonores: a___", "a": ["apitxat"], "e": "En apitxat, «casa» i «caça» es pronuncien igual, amb s sorda."},
      {"q": "Escriu el nom de la varietat lèxica pròpia d'un grup social, sovint per a no ser entés pels altres: a___", "a": ["argot"], "e": "L'argot és una varietat social."},
      {"q": "Escriu la forma valenciana de «avui»: h___", "a": ["hui"], "e": "Hui és la forma pròpia del valencià i és normativa."},
      {"q": "Escriu el nom de la ciutat de Sardenya on es parla la nostra llengua: l'A___", "a": ["l'Alguer", "Alguer"], "e": "L'alguerés pertany al bloc oriental."},
      {"q": "Escriu el terme mèdic culte per a «mal de cap»: c___", "a": ["cefalàlgia", "cefalea"], "e": "Cefalàlgia o cefalea són termes del llenguatge d'especialitat."},
      {"q": "Escriu el nom de la varietat lingüística pròpia d'un territori: d___", "a": ["dialecte"], "e": "Els dialectes són les varietats geogràfiques d'una llengua."},
      {"q": "Escriu el nom, propi d'un certificat, que designa la mort d'una persona: d___", "a": ["defunció"], "e": "Certificat de defunció; en registre col·loquial es diu «la mort»."},
      {"q": "Completa la salutació d'una carta formal: «B___ senyora:»", "a": ["Benvolguda"], "e": "Benvolgut, benvolguda: fórmula de salutació formal."}
    ]
  }
]$data$::jsonb) AS t(
  id uuid, type text, sort_order smallint, title text, name text,
  content text, icon text, color text, exercises jsonb
);

INSERT INTO public.resources (id, name, type, category, content, difficulty, xp_earned, sort_order, metadata)
SELECT id, name, type, 'lexic_semantica', content, 'C1', 15, sort_order,
       jsonb_build_object('icon', icon, 'color', color, 'section_name', title)
FROM practice_catalog
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  category = EXCLUDED.category,
  content = EXCLUDED.content,
  difficulty = EXCLUDED.difficulty,
  xp_earned = EXCLUDED.xp_earned,
  sort_order = EXCLUDED.sort_order,
  -- Conserva la lliçó fixa («Aprendre lliçó»), si una migració posterior n'hi afig.
  metadata = EXCLUDED.metadata || jsonb_strip_nulls(jsonb_build_object('lesson', resources.metadata -> 'lesson'));

DELETE FROM public.practice_exercises e
USING practice_catalog c
WHERE e.resource_id = c.id AND e.level = 'C1';

INSERT INTO public.practice_exercises (resource_id, level, position, kind, prompt, options, answers, explanation)
SELECT c.id, 'C1', x.ord,
       CASE WHEN x.e ? 'a' THEN 'fill' ELSE 'choice' END,
       x.e->>'q',
       CASE WHEN x.e ? 'o' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'o')) END,
       CASE WHEN x.e ? 'a' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'a')) ELSE ARRAY[x.e->'o'->>0] END,
       x.e->>'e'
FROM practice_catalog c
CROSS JOIN LATERAL jsonb_array_elements(c.exercises) WITH ORDINALITY AS x(e, ord);

DROP TABLE practice_catalog;
